-- Generated by scripts/bsc_config/build_seed.py from the Hayat BSC handover and the decisions of 2026-10-20.
-- Applied once by apply_bsc_config.ps1; afterwards the default.map_bsc_* tables are the source of truth.









SELECT 'CUS_PREMS', hospital_id, year, month, toFloat64(prems_score_actual), 1, source_sheet, now64(3), 'seed', 'seed from handover 2026-10-20', 0
FROM default.bsc_patient_satisfaction WHERE prems_score_actual IS NOT NULL AND hospital_id BETWEEN 1 AND 8
UNION ALL
SELECT 'CUS_COMPLAINT_RATE', hospital_id, year, month, toFloat64(patient_complaint_rate_actual), 0, source_sheet, now64(3), 'seed', 'seed from handover 2026-10-20', 0
FROM default.bsc_patient_satisfaction WHERE patient_complaint_rate_actual IS NOT NULL AND hospital_id BETWEEN 1 AND 8;
